-- 7. views and functions
create or replace view public.area_scores as  SELECT r.learner_id,
    r.term_id,
    c.area_id,
    (round(avg((r.score)::integer)))::integer AS score,
    count(*) AS questions_scored
   FROM (assessment_records r
     JOIN competencies c ON ((c.id = r.competency_id)))
  WHERE ((r.rater_role = 'teacher'::text) AND (r.score ~ '^[0-5]$'::text) AND (NOT (EXISTS ( SELECT 1
           FROM assessment_records x
          WHERE (x.revision_of = r.id)))))
  GROUP BY r.learner_id, r.term_id, c.area_id;
create or replace view public.rater_agreement as  SELECT t.learner_id,
    t.term_id,
    t.competency_id,
    (t.score)::integer AS teacher_score,
    (d.score)::integer AS director_score,
    abs(((t.score)::integer - (d.score)::integer)) AS gap
   FROM (assessment_records t
     JOIN assessment_records d ON (((d.learner_id = t.learner_id) AND (d.term_id = t.term_id) AND (d.competency_id = t.competency_id) AND (d.rater_role = 'director'::text))))
  WHERE ((t.rater_role = 'teacher'::text) AND (t.score ~ '^[0-5]$'::text) AND (d.score ~ '^[0-5]$'::text) AND (NOT (EXISTS ( SELECT 1
           FROM assessment_records x
          WHERE (x.revision_of = t.id)))) AND (NOT (EXISTS ( SELECT 1
           FROM assessment_records x
          WHERE (x.revision_of = d.id)))));
CREATE OR REPLACE FUNCTION public.staff_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select role from public.staff where id = auth.uid() $function$
;
CREATE OR REPLACE FUNCTION public.matan_is_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from staff s where s.id = auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.matan_is_head()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from staff s where s.id = auth.uid() and s.role = 'head');
$function$
;
CREATE OR REPLACE FUNCTION public.matan_can_edit_learner(lid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.matan_is_admin() or exists (
    select 1 from learners l join classes c on c.id = l.class_id
    where l.id = lid and c.teacher_id = auth.uid());
$function$
;
CREATE OR REPLACE FUNCTION public.matan_goal_learner(gid uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select learner_id from learner_goals where id = gid;
$function$
;
CREATE OR REPLACE FUNCTION public.matan_is_senior()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from staff s where s.id = auth.uid() and s.role = 'senior');
$function$
;
CREATE OR REPLACE FUNCTION public.matan_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from staff s where s.id = auth.uid() and s.role in ('head','senior'));
$function$
;
CREATE OR REPLACE FUNCTION public.matan_guard_tier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (tg_op = 'INSERT' and new.confirmed_tier is not null and not public.matan_is_admin())
     or (tg_op = 'UPDATE' and new.confirmed_tier is distinct from old.confirmed_tier and not public.matan_is_admin()) then
    raise exception 'Only the director or a senior teacher can confirm a tier.';
  end if;
  new.updated_at := now();
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.matan_guard_report_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (tg_op = 'INSERT' and new.head_comment is not null and not public.matan_is_head())
     or (tg_op = 'UPDATE' and new.head_comment is distinct from old.head_comment and not public.matan_is_head()) then
    raise exception 'Only the director can write the director''s comment.';
  end if;
  new.updated_at := now();
  return new;
end $function$
;

-- 8. triggers
CREATE TRIGGER learner_tiers_guard BEFORE INSERT OR UPDATE ON public.learner_tiers FOR EACH ROW EXECUTE FUNCTION matan_guard_tier();
CREATE TRIGGER report_comments_guard BEFORE INSERT OR UPDATE ON public.report_comments FOR EACH ROW EXECUTE FUNCTION matan_guard_report_comment();

