  using (matan_is_staff());
create policy add_records on public.assessment_records as PERMISSIVE for INSERT to authenticated
  with check (((rater_id = auth.uid()) AND (rater_role =
CASE staff_role()
    WHEN 'head'::text THEN 'director'::text
    ELSE 'teacher'::text
END) AND ((revision_of IS NULL) OR (EXISTS ( SELECT 1
   FROM assessment_records o
  WHERE ((o.id = assessment_records.revision_of) AND (o.rater_id = auth.uid())))))));
