create policy read_learning_areas on public.learning_areas as PERMISSIVE for SELECT to authenticated
  using ((staff_role() IS NOT NULL));
create policy add_parent_messages on public.parent_messages as PERMISSIVE for INSERT to authenticated
  with check (((staff_role() IS NOT NULL) AND (staff_id = auth.uid())));
create policy admin_all_parent_messages on public.parent_messages as PERMISSIVE for ALL to authenticated
  using (matan_is_admin())
  with check (matan_is_admin());
create policy read_parent_messages on public.parent_messages as PERMISSIVE for SELECT to authenticated
  using ((staff_role() IS NOT NULL));
create policy add_variants on public.question_variants as PERMISSIVE for INSERT to authenticated
  with check (((staff_role() IS NOT NULL) AND (source = 'teacher'::text) AND (created_by = auth.uid()) AND ((status = 'pending'::text) OR (staff_role() = 'head'::text))));
create policy admin_all_question_variants on public.question_variants as PERMISSIVE for ALL to authenticated
  using (matan_is_admin())
  with check (matan_is_admin());
create policy director_approves on public.question_variants as PERMISSIVE for UPDATE to authenticated
  using ((staff_role() = 'head'::text))
  with check ((staff_role() = 'head'::text));
create policy read_variants on public.question_variants as PERMISSIVE for SELECT to authenticated
  using (((staff_role() IS NOT NULL) AND ((status = 'approved'::text) OR (source = 'curriculum'::text) OR (created_by = auth.uid()) OR (staff_role() = 'head'::text))));
create policy remove_own_pending on public.question_variants as PERMISSIVE for DELETE to authenticated
  using (((created_by = auth.uid()) AND (source = 'teacher'::text) AND (status = 'pending'::text)));
create policy rc_add on public.report_comments as PERMISSIVE for INSERT to authenticated
  with check (matan_can_edit_learner(learner_id));
create policy rc_change on public.report_comments as PERMISSIVE for UPDATE to authenticated
  using (matan_can_edit_learner(learner_id))
  with check (matan_can_edit_learner(learner_id));
create policy rc_read on public.report_comments as PERMISSIVE for SELECT to authenticated
  using (matan_is_staff());
create policy add_reviews on public.score_reviews as PERMISSIVE for INSERT to authenticated
  with check (((staff_role() = 'head'::text) AND (reviewed_by = auth.uid())));
create policy read_reviews on public.score_reviews as PERMISSIVE for SELECT to authenticated
  using ((staff_role() IS NOT NULL));
create policy read_staff on public.staff as PERMISSIVE for SELECT to authenticated
  using ((staff_role() IS NOT NULL));
create policy staff_head_write on public.staff as PERMISSIVE for ALL to authenticated
  using (matan_is_head())
  with check (matan_is_head());
create policy sa_read on public.staff_attendance as PERMISSIVE for SELECT to authenticated
  using ((matan_is_admin() OR (staff_id = auth.uid())));
create policy sa_write on public.staff_attendance as PERMISSIVE for ALL to authenticated
  using (matan_is_admin())
  with check (matan_is_admin());
create policy add_own_notes on public.teacher_notes as PERMISSIVE for INSERT to authenticated
  with check ((staff_id = auth.uid()));
create policy admin_all_teacher_notes on public.teacher_notes as PERMISSIVE for ALL to authenticated
  using (matan_is_admin())
  with check (matan_is_admin());
create policy read_teacher_notes on public.teacher_notes as PERMISSIVE for SELECT to authenticated
  using ((staff_role() IS NOT NULL));
create policy read_terms on public.terms as PERMISSIVE for SELECT to authenticated
  using ((staff_role() IS NOT NULL));

